SET search_path=salesflow,public;
SELECT set_config('sf.rt',:'runtime_token',false),set_config('sf.rt2',:'runtime_token_2',false),set_config('sf.op',:'operator_token',false),set_config('sf.sch',:'scheduler_token',false),set_config('sf.manifest',convert_from(decode(:'activation_manifest_b64','base64'),'UTF8'),false),set_config('sf.manifest_hash',:'activation_manifest_hash',false);
CREATE TEMP TABLE evidence(id text PRIMARY KEY);
